#!/bin/bash
# WAIT FOR tv6hue TO FINISH ITS 20 EPOCHS, THEN LAUNCH THE L2-SP 1e-2 ARM.
#
# Usage:  ./shell_scripts/chain_l2sp_1e2_after_tv6hue.sh      (run it as a tracked background task,
#         NOT with a trailing & inside a compound command: $! there is the wrapper subshell, not
#         this script, and on 2026-10-26 that made three "stopped the old chain" attempts kill the
#         wrong pid while both real chains kept running.)
#
# DO NOT EDIT THIS FILE WHILE AN INSTANCE IS EXECUTING IT. bash reads a script lazily, so an edit
# shifts the byte offsets under the running shell; editing this chain's predecessor mid-run on
# 2026-10-26 produced "line 31: /extra_training: No such file or directory" from a cd at line 26
# and ended with two chains and six processes on three cards.
#
# NO KILL ANYWHERE IN HERE. tv6hue has --epochs 20 and exits on its own, so the chain waits for
# its ranks to be gone and the cards to be free rather than stopping a run itself. A chain that
# can kill is a chain that can kill the wrong thing at 3am; this one can only ever fail to launch.
#
# RANK PIDS ARE EXPLICIT, never derived by pattern: pgrep/pkill matches the shell running them and
# self-killed the session twice on 2026-10-18. These pids are only READ (/proc/<pid> existence).
set -u
cd /home/ebrahim/confidence_recalibration/extra_training
PY_BIN=/home/ebrahim/Protenix/.venv/bin/python
RANKS="3559013 3559014 3559015"
# This script records its OWN pid, so stopping the chain never needs a pattern match and
# never needs $! from a compound command (which is the wrapper subshell, not this script).
echo $$ > training/runs/l2sp_1e2_chain_pid
# tv6hue resumed from ij24wr's epoch 1, so it evaluates epochs 2..20 == 19 of its own epochs.
WANT=19
echo "$(TZ=America/New_York date '+%F %-I:%M %p %Z') chain armed; waiting for tv6hue (ranks $RANKS)"
for i in $(seq 1 6000); do          # 50h ceiling at 30s
  alive=0; for P in $RANKS; do [ -d "/proc/$P" ] && alive=1; done
  [ "$alive" = "0" ] && break
  sleep 30
done
alive=0; for P in $RANKS; do [ -d "/proc/$P" ] && alive=1; done
[ "$alive" = "1" ] && { echo "$(TZ=America/New_York date '+%F %-I:%M %p') TIMEOUT: tv6hue still running, NOT launching"; exit 1; }
DONE=$(ls -1 training/runs/tv6hue/metric_train_ep*.json 2>/dev/null | wc -l)
echo "$(TZ=America/New_York date '+%F %-I:%M %p') tv6hue gone after $DONE evaluated epoch(s)"
# A RUN THAT DIED EARLY IS NOT A RUN THAT FINISHED, and launching the next arm over a crash would
# bury the crash under eight hours of new output.
if [ "$DONE" -lt "$WANT" ]; then
  echo "$(TZ=America/New_York date '+%F %-I:%M %p') REFUSING: expected $WANT evaluated epochs (2..20), found $DONE. Look at tv6hue first."
  exit 1
fi
for i in $(seq 1 60); do
  BUSY=$($PY_BIN -I run_logging/cards_busy.py 2>&1 | tail -1)
  [ "$BUSY" = "0" ] && break
  sleep 10
done
BUSY=$($PY_BIN -I run_logging/cards_busy.py 2>&1 | tail -1)
# cards_busy.py FAILS CLOSED: it prints UNKNOWN and exits 2 if it cannot resolve the target UUIDs,
# so anything other than a literal 0 refuses. Before 2026-10-26 it reported "free" whenever the
# GPU holders were gone, which would have let this chain launch onto occupied cards.
[ "$BUSY" = "0" ] || { echo "$(TZ=America/New_York date '+%F %-I:%M %p') REFUSING: cards still occupied ($BUSY)"; exit 1; }
echo "$(TZ=America/New_York date '+%F %-I:%M %p') launching the L2-SP 1e-2 arm"
./shell_scripts/launch_fullhead_l2sp_1e2.sh
rc=$?
# The trailing echo must NOT be the last word on success: a chain that prints "launched" after a
# failed launcher is how a dead arm looked fine for an hour on 2026-10-26.
if [ "$rc" = "0" ]; then
  echo "$(TZ=America/New_York date '+%F %-I:%M %p') l2sp 1e-2 launcher returned 0"
else
  echo "$(TZ=America/New_York date '+%F %-I:%M %p') LAUNCH FAILED: launcher returned $rc"
fi
exit $rc
